def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    window = 10
    if n < window:
        recent = history
    else:
        recent = history[-window:]
    recent_def = 0
    for _, opp in recent:
        if opp == 'D':
            recent_def += 1
    if recent_def >= 3:
        return 'D'
    return 'C'
